#include <cstddef>
#include <span>

int sumArray(const int* data, std::size_t length)
{
    int total{ 0 };
    for (std::size_t i{ 0 }; i < length; ++i)
    {
        total += data[i];
    }
    return total;
}

int sumSpan(std::span<const int> data)
{
    int total{ 0 };
    for (int value : data)
    {
        total += value;
    }
    return total;
}

unitTests:
TEST("sumArray") { const int a[]{ 1, 2, 3, 4 }; CHECK_EQ(sumArray(a, 4), 10); CHECK_EQ(sumArray(a, 2), 3); CHECK_EQ(sumArray(a, 0), 0); }
TEST("sumSpan with a C array") { const int a[]{ 5, 6, 7 }; CHECK_EQ(sumSpan(a), 18); }
TEST("sumSpan with a vector and an array") { const std::vector<int> v{ 1, 1, 1 }; const std::array<int, 2> arr{ 40, 2 }; CHECK_EQ(sumSpan(v), 3); CHECK_EQ(sumSpan(arr), 42); }

